import os
import json
import logging
import requests
from collections import OrderedDict
from taf.sw.nrdim.nrdimapi.getData import codeGenerator


class NrdimRequest(object):

    _NRDIM_WEBSITE = "http://5gtables.eecloud.dynamic.nsn-net.net"
    _GET_SCF_MEDIATION_URL = "/NRDim/NRDimImport/SCFmediation.json"
    _GET_ATTRIBUTES_URL = "/NRDim/NRDimImport/attributes.json"

    def __init__(self, url=None):
        self._request_base_url = url or self._NRDIM_WEBSITE

    def request_scf_mediation_data(self):
        """
        Get NRDIM scf mediation data
        http://5gtables.eecloud.dynamic.nsn-net.net/NRDim/NRDimImport/SCFmediation.json
        :return: nrdim scf mediation data
        :rtype: OrderedDict
        """
        request_url = self._build_scf_mediation_url()
        response = self._send_request(url=request_url)
        return json.loads(response.content, object_pairs_hook=OrderedDict)

    def _build_scf_mediation_url(self):
        return self._request_base_url + self._GET_SCF_MEDIATION_URL

    def request_attributes_json(self):
        request_url = self._build_attributes_url()
        response = self._send_request(url=request_url)
        return json.loads(response.content, object_pairs_hook=OrderedDict)

    def _build_attributes_url(self):
        return self._request_base_url + self._GET_ATTRIBUTES_URL

    def get_throughput(self, gnb_params, attributes_file=None, harq_process=False, latency_budget=False):
        # Get all attributes in the structure codeDescription from attributes.json
        # (used also in JavaScript for launching requests)
        if attributes_file:
            code_description = self._load_code_description_from_file(attributes_file)
        else:
            code_description = self._load_code_description_online()

        code = codeGenerator(code_description, gnb_params)

        # Generate all parameters for the GET request
        # request_params = self._generate_params_for_request(code_description, gnb_params)

        # Mediation (for some attributes, I use real values in Python, not integer as external tools):
        # request_params = mediate_parameters(request_params, verbose=True)
        request_params = None
        # Prepare the URL to execute Python:
        request_url = self._build_get_throughput_url(code, request_params, harq_process, latency_budget)

        response = self._send_request(url=request_url)
        return response.content

    def _send_request(self, url, method='GET', headers=None, data=None, params=None):
        try:
            logging.info("{} request with url={}".format(method, url))
            return requests.request(method=method, url=url, headers=headers, data=data, params=params)
        except requests.exceptions.ConnectionError as e:
            logging.error(str(e))
            raise Exception("please check your network with url '{}'".format(url))

    def _load_code_description_online(self):
        attributes_json = self.request_attributes_json()
        return self._extract_code_description(attributes_json)

    def _load_code_description_from_file(self, attributes_file):
        if not os.path.isfile(attributes_file):
            raise Exception("{} json file not existed".format(attributes_file))

        with open(attributes_file, 'r') as file_handler:
            attributes_json = json.load(file_handler, object_pairs_hook=OrderedDict)
            return self._extract_code_description(attributes_json)

    def _extract_code_description(self, attributes_json):
        code_description = {}
        for info in attributes_json["NRDim"]:
            code_description[info[0]] = info
        return code_description

    @staticmethod
    def _generate_params_for_request(code_description, gnb_params):
        request_params = {}
        for attribute in code_description:
            attribute_info = code_description[attribute]
            if len(attribute_info) >= 8:
                if attribute not in gnb_params:
                    logging.debug("{} not in {}".format(attribute, gnb_params))
                    continue
                request_params[code_description[attribute][7]] = gnb_params[attribute]
        return request_params

    def _build_get_throughput_url(self, code, params, harq_process, latency_budget):
        # Prepare the URL to execute Python:
        request_url = "/NRDim_execServer.php?"
        request_url += "co=" + code

        if harq_process:
            request_url += "&hp=1"

        if latency_budget:
            request_url += "&lb=1"

        '''
        0: JSON will be generated.
        1: no JSON file will be generated.
        JSON files are used for the webUI interface.
        '''
        request_url += "&nj=1"

        '''
        0: no image.
        1: image will be generated for each reference slot.
        '''
        request_url += "&ig=0"

        return self._request_base_url + request_url
